INSERT INTO [Categories] ([CategoryId], [CategoryName], [Description]) VALUES (1, N'Laptop Gaming', N'Trang bị CPU hiệu năng cao (dòng H/HX), GPU rời NVIDIA GeForce RTX, tản nhiệt buồng hơi, màn hình tần số quét từ 144Hz trở lên.');
INSERT INTO [Categories] ([CategoryId], [CategoryName], [Description]) VALUES (2, N'Laptop Học tập - Văn phòng', N'Thiết kế thực dụng, thời lượng pin tốt, bàn phím gõ êm, tối ưu tác vụ tin học văn phòng, lướt web, học online.');
INSERT INTO [Categories] ([CategoryId], [CategoryName], [Description]) VALUES (3, N'Laptop Đồ họa - Kỹ thuật', N'Màn hình chuẩn màu sRGB/DCI-P3, CPU/GPU mạnh mẽ tối ưu cho AutoCAD, SolidWorks, Premiere, lập trình và render.');
INSERT INTO [Categories] ([CategoryId], [CategoryName], [Description]) VALUES (4, N'Laptop Mỏng nhẹ - Doanh nhân', N'Trọng lượng dưới 1.4kg, vỏ kim loại/magie cao cấp, độ bảo mật cao (vân tay, nhận diện khuôn mặt), thiết kế sang trọng.');
INSERT INTO [Categories] ([CategoryId], [CategoryName], [Description]) VALUES (5, N'Workstation Di Động', N'Trạm làm việc di động với CPU cực mạnh, RAM mở rộng lớn, GPU chuyên dụng Studio/Quadro, độ bền chuẩn quân đội.');
