-- =========================================================================
-- KIá»‚M TRA Tá»”NG Káº¾T SAU KHI KHá»žI Táº O CSDL
-- =========================================================================
SELECT t.NAME AS TableName, i.Rows AS TotalRows
FROM sys.tables t
JOIN sys.partitions i ON t.object_id = i.object_id
WHERE i.index_id IN (0, 1)
ORDER BY t.NAME;
GO

